{
  "title": "Certificate and Open Badge Generation and Management",
  "description": "This documentation report synthesizes insights into the 'Digital Certificates, Open Badges, and Credential Issuance' feature cluster, providing a comprehensive system for managing, issuing, and verifying digital credentials within the platform. This includes both PDF-based certificates and Open Badges, primarily managed through the main Rails application with integrations for external services like proctoring and achievement tracking. The system encompasses template management, user-facing display, rendering, verification, and background processing for credential-related assets.",
  "functional_domain": "Digital Credentialing and Verification",
  "key_components_and_functionality": [
    {
      "section_title": "Credential Template Management",
      "details": "The system provides robust administrative interfaces for defining and managing templates for both digital certificates and Open Badges.",
      "sub_sections": [
        {
          "title": "Certificate Template Management",
          "description": "Managed by the `Course::Admin::CertificateTemplatesController`, this interface allows administrators to create, update, delete, and preview certificate templates. These templates, represented by `Certificate::Template` objects, support various attributes including `certificate_type`, `dynamic_content` (SVG), `qrcode_x`, `qrcode_y`, and an associated PDF file upload. File uploads are handled via the `FileUpload` utility for `application/pdf` content. Deletion of a template is prevented if `Certificate::Record` instances are associated with it. Permissions are controlled by `certificate.template.manage`, granted to `xikolo.admins`.",
          "components": [
            "Course::Admin::CertificateTemplatesController",
            "Certificate::Template",
            "FileUpload"
          ]
        },
        {
          "title": "Open Badge Template Management",
          "description": "Similar to certificates, `Course::Admin::OpenBadgeTemplatesController` provides an administrative interface for `Certificate::OpenBadgeTemplate` objects. Administrators can create, update, and delete Open Badge templates, defining their `name`, `description`, and uploading a PNG image file using `FileUpload` for `image/png` content. Permissions are also tied to `certificate.template.manage`.",
          "components": [
            "Course::Admin::OpenBadgeTemplatesController",
            "Certificate::OpenBadgeTemplate",
            "FileUpload"
          ]
        }
      ]
    },
    {
      "section_title": "User-Facing Credential Display and Issuance",
      "details": "The `Course::CertificatesController` handles the user's view of their earned credentials and the process of displaying and generating them.",
      "sub_sections": [
        {
          "title": "Credential Display",
          "description": "The `index` action retrieves user achievements from an external service via `Restify` and displays course-related documents. The `show` action displays a specific certificate (e.g., 'Record of Achievement' or `ROA`) and an associated Open Badge for the `current_user`. Open Badges are 'baked' using `Certificate::OpenBadgeTemplate#bake!`. Meta tags are dynamically generated for SEO and social sharing, including Open Graph image tags if an Open Badge is available.",
          "components": [
            "Course::CertificatesController",
            "Restify",
            "Certificate::OpenBadgeTemplate"
          ]
        },
        {
          "title": "Certificate Rendering and Download",
          "description": "The `render_certificate` action allows users to download PDF certificates. For proctored courses, a critical check `ensure_proctoring_passed!` is performed, verifying proctoring status via `Proctoring::SmowlAdapter`. Failure to pass proctoring raises a `CertificateNotAllowed` exception. The actual PDF generation is delegated to the `Certificate::Record::Render` operation, which utilizes `Certificate::RecordRenderer`. This renderer uses the `Prawn` and `Prawn::QRCode` gems to construct the PDF, supporting dynamic content (SVG), QR codes, proctoring images, a transcript of records table, and custom font loading.",
          "components": [
            "Course::CertificatesController",
            "Proctoring::SmowlAdapter",
            "Certificate::Record::Render",
            "Certificate::RecordRenderer",
            "Prawn",
            "Prawn::QRCode"
          ]
        },
        {
          "title": "Open Badge Baking",
          "description": "Open Badges are generated through a 'baking' process, which involves embedding user-specific data into a template. This process is facilitated by the `OpenBadgeBakery` component, ensuring that Open Badges are properly constructed and verifiable.",
          "components": [
            "OpenBadgeBakery"
          ]
        }
      ]
    },
    {
      "section_title": "Certificate Verification",
      "details": "The `verify` action in `Course::CertificatesController` provides a public endpoint for verifying certificates using a unique `verification_code`. It retrieves the `Certificate::Record` and, if eligible, bakes and displays the corresponding Open Badge.",
      "components": [
        "Course::CertificatesController",
        "Certificate::Record"
      ]
    },
    {
      "section_title": "Proctoring Image Management",
      "details": "The `Proctoring::UploadCertificateImageJob` is designed to fetch a user's proctoring image from SMOWL and upload it to S3 for inclusion in certificates. This job is queued with `eventual` priority and includes retry logic for `Proctoring::ServiceError`.",
      "components": [
        "Proctoring::UploadCertificateImageJob"
      ]
    }
  ],
  "inferred_models_and_presenters": [
    {
      "name": "Certificate::Template",
      "description": "Represents a customizable template for digital certificates, storing design parameters, dynamic content, QR code positioning, and linking to the PDF template file."
    },
    {
      "name": "Certificate::OpenBadgeTemplate",
      "description": "Represents a template for Open Badges, storing badge metadata (name, description) and linking to the badge image file."
    },
    {
      "name": "Certificate::Record",
      "description": "Represents an issued digital certificate or credential to a specific user for a specific course, including a unique verification code."
    },
    {
      "name": "Course::CertificateTemplatePresenter",
      "description": "A presenter for `Certificate::Template` objects, used for display purposes."
    },
    {
      "name": "Certificate::RecordPresenter",
      "description": "A presenter for `Certificate::Record` objects, used for display purposes."
    }
  ],
  "technical_debt_and_observations": [
    {
      "issue": "Incomplete Proctoring Image Upload Job",
      "description": "The `perform` method of `Proctoring::UploadCertificateImageJob` is currently empty. This indicates that the functionality to upload proctoring images to S3 for certificates is not yet implemented or is non-functional, despite the job being scheduled.",
      "source": "app/jobs/proctoring/upload_certificate_image_job.rb"
    },
    {
      "issue": "Hardcoded Proctoring Image Position",
      "description": "The `Certificate::RecordRenderer` uses fixed coordinates (`at: [16.1, 754]`, `width: 77.2`) for placing the proctoring image on the PDF. This could lead to layout issues if certificate templates vary significantly in design or if the image size/aspect ratio changes.",
      "source": "app/lib/certificate/record_renderer.rb"
    },
    {
      "issue": "Font Handling Complexity",
      "description": "The `RecordRenderer` includes specific workarounds for Prawn's font handling, such as disabling subsetting (`subset: false`) and setting custom font identifiers. This suggests underlying complexities or limitations with the PDF generation library that required explicit mitigation.",
      "source": "app/lib/certificate/record_renderer.rb"
    },
    {
      "issue": "Multiple `Acfs.run` Calls",
      "description": "The `Course::CertificatesController` makes multiple `Acfs.run` calls within a single action (`index`, `show`). While `Acfs` is an asynchronous framework, calling `run` multiple times in a single action might indicate a less optimized data fetching strategy if not carefully managed to avoid redundant processing.",
      "source": "app/controllers/course/certificates_controller.rb"
    },
    {
      "issue": "Proctoring Check Scope",
      "description": "The `ensure_proctoring_passed!` check is only applied when rendering the `CERT` type of certificate, not for other types like `ROA`. This might be intentional but warrants consideration for consistency if all official credentials should require proctoring for download.",
      "source": "app/controllers/course/certificates_controller.rb"
    },
    {
      "issue": "`TODO` in `check_course_eligibility`",
      "description": "An explicit `TODO` comment highlights an acknowledged area for improvement in the course eligibility checks, suggesting potential gaps or desired enhancements in access control logic.",
      "source": "app/controllers/course/certificates_controller.rb"
    }
  ]
}

